import test from 'node:test';import assert from 'node:assert/strict';import {confirmedMerge} from './merge.mjs';
const base='a'.repeat(40),head='b'.repeat(40),merged='c'.repeat(40),tree='d'.repeat(40);
function fake({fail=false,changed=false,badTree=false}={}) {const calls=[];let done=false;return{calls,request:async(path,method='GET')=>{calls.push({path,method});if(method==='PUT'){done=true;if(fail)throw Object.assign(Error('502'),{status:502});return{merged:true,sha:merged};}if(path.endsWith('/pulls/25'))return{merged:done,state:'closed',head:{sha:changed?base:head},merge_commit_sha:merged};if(path.endsWith('/heads/main'))return{object:{sha:done?merged:base}};if(path.endsWith('/commits/'+head))return{tree:{sha:tree}};return{parents:[{sha:base}],tree:{sha:badTree?base:tree}};}};}
for(const fail of [false,true])test(fail?'recovers a merge accepted behind a 502 without merging twice':'verifies exact merge contents',async()=>{const f=fake({fail});assert.equal(await confirmedMerge({...f,repo:'instancelabs/test',number:25,head,base,wait:async()=>{}}),merged);assert.equal(f.calls.filter(c=>c.method==='PUT').length,1);});
test('stops when PR changed',async()=>{const f=fake({changed:true});await assert.rejects(confirmedMerge({...f,repo:'instancelabs/test',number:25,head,base,wait:async()=>{}}));});
test('stops when merge contents differ',async()=>{const f=fake({badTree:true});await assert.rejects(confirmedMerge({...f,repo:'instancelabs/test',number:25,head,base,wait:async()=>{}}));});
test('does not retry permission denial',async()=>{let calls=0;await assert.rejects(confirmedMerge({request:async()=>{calls++;throw Object.assign(Error('denied'),{status:403});},repo:'instancelabs/test',number:25,head,base,wait:async()=>{}}));assert.equal(calls,1);});
test('retries are bounded while GitHub keeps the request unconfirmed',async()=>{let puts=0;await assert.rejects(confirmedMerge({repo:'instancelabs/test',number:25,head,base,wait:async()=>{},request:async(path,method)=>{if(method==='PUT'){puts++;throw Object.assign(Error('502'),{status:502});}return path.endsWith('/heads/main')?{object:{sha:base}}:{head:{sha:head},state:'open',merged:false};}}));assert.equal(puts,5);});
